declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('deals.manage');header('Content-Type: application/json; charset=utf-8');try{verify_csrf();$dealId=(int)($_POST['deal_id']??0);$stageId=(int)($_POST['stage_id']??0);$s=db()->prepare('SELECT * FROM pipeline_stages WHERE id=? AND is_active=1');$s->execute([$stageId]);$stage=$s->fetch();if(!$dealId||!$stage)throw new RuntimeException('Etapa o negocio inválido.');$status=$stage['is_closed_won']?'won':($stage['is_closed_lost']?'lost':'open');db()->prepare('UPDATE deals SET stage_id=?,probability=?,status=?,closed_at=? WHERE id=?')->execute([$stageId,(int)$stage['probability'],$status,$status==='open'?null:date('Y-m-d H:i:s'),$dealId]);echo json_encode(['success'=>true,'probability'=>(int)$stage['probability'],'color'=>$stage['color'],'status'=>$status,'convert_url'=>$status==='won'?'deal_convert_service.php?id='.$dealId:null]);}catch(Throwable$e){http_response_code(422);echo json_encode(['success'=>false,'error'=>$e->getMessage()]);}
